local function describe(label,s)
  print(label,s.width,s.height,s.colorMode,s.transparentColor,s.colorSpace.name,s.colorSpace==ColorSpace(),s.colorSpace==ColorSpace{sRGB=true})
end
local a=ImageSpec();describe('default',a)
local b=ImageSpec{width=2,height=3,colorMode=ColorMode.INDEXED,transparentColor=7,colorSpace=ColorSpace{sRGB=true}};describe('table',b)
assert(b.colorSpace==ColorSpace())
