c.width=2;c.colorSpace=ColorSpace{sRGB=true};local profile=c.colorSpace;profile.name='Named';assert(c.colorSpace.name=='');c.colorSpace=profile;profile.name='Changed';assert(c.colorSpace.name=='Named')
local equal=ImageSpec(c);equal.colorSpace=ColorSpace{sRGB=true};assert(equal==c)
local i=Image(c);assert(i:getPixel(0,0)==7);describe('image',i.spec)
c.width=4;c.transparentColor=8;assert(i.width==2 and i.spec.transparentColor==7)
local detached=i.spec;detached.width=6;detached.colorSpace=ColorSpace();assert(i.width==2 and i.spec.colorSpace.name=='Named')
local clone=Image(i);local crop=Image(i,Rectangle(-1,0,3,1));assert(clone.spec.colorSpace==ColorSpace() and crop.spec.colorSpace==ColorSpace());assert(clone.spec.transparentColor==7 and crop:getPixel(0,0)==7)
assert(not pcall(function()return i.colorSpace end));assert(not pcall(function()i.colorSpace=ColorSpace() end))
local s=Sprite(c);describe('sprite',s.spec);assert(s.cels[1].image:getPixel(0,0)==0 and #s.palettes[1]==256)
local ss=s.spec;ss.width=1;assert(s.width==4 and s.spec==s.spec)
local rendered=Image(s);assert(rendered.spec.colorSpace==s.colorSpace and rendered.spec.colorSpace.name==s.colorSpace.name)
local original=s.cels[1].image;local savedSpec=original.spec;local cs=ColorSpace();cs.name='Working None';s:assignColorSpace(cs)
assert(original.spec.colorSpace.name=='Working None' and savedSpec.colorSpace.name=='Named' and rendered.spec.colorSpace.name=='Named')
local layer=s:newLayer();local cel=s:newCel(layer,1,i);assert(cel.image.spec.colorSpace==ColorSpace() and cel.image.spec.transparentColor==8)
s:assignColorSpace(ColorSpace{sRGB=true});assert(cel.image.spec.colorSpace==s.colorSpace and cel.image.spec.transparentColor==8)
cel.image=clone;assert(cel.image.spec.colorSpace==ColorSpace())
